//! Emits `crates/kronosdb-protocol/src/generated.rs`.
//!
//! Decoders borrow strings, bytes and records from the frame buffer, so a
//! decoded frame allocates only for its lists. Encoders append to a
//! `Vec<u8>` and fail rather than truncate when a length overflows its width.

use std::fmt::Write;

use crate::schema::{EVENT_RECORD, Enum, Schema, Struct, Type, Union, Width};

pub fn emit(schema: &Schema, schema_hash: &str) -> String {
    let mut o = String::new();
    writeln!(
        o,
        "// @generated by protocol-gen from protocol/kronosdb.schema. Do not edit;"
    )
    .unwrap();
    writeln!(o, "// change the schema and run `just protocol`.").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "#![allow(clippy::all)]").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "use crate::codec::*;").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "/// The protocol version this code speaks.").unwrap();
    writeln!(o, "pub const PROTOCOL_VERSION: u16 = {};", schema.version).unwrap();
    writeln!(
        o,
        "/// CRC32C of the schema source, for checking generated code is in sync."
    )
    .unwrap();
    writeln!(o, "pub const SCHEMA_HASH: &str = \"{schema_hash}\";").unwrap();

    for e in &schema.enums {
        emit_enum(&mut o, e);
    }
    for u in &schema.unions {
        emit_union(&mut o, schema, u);
    }
    for s in &schema.structs {
        emit_struct(&mut o, schema, s);
    }
    emit_frame_enum(&mut o, schema);
    emit_record_json(&mut o);
    o
}

fn doc(o: &mut String, indent: &str, lines: &[String]) {
    for line in lines {
        if line.is_empty() {
            writeln!(o, "{indent}///").unwrap();
        } else {
            writeln!(o, "{indent}/// {line}").unwrap();
        }
    }
}

fn shout(name: &str) -> String {
    name.to_ascii_uppercase()
}

/// `initial_result` → `InitialResult`, for enum variants.
fn pascal(name: &str) -> String {
    name.split('_')
        .map(|part| {
            let mut c = part.chars();
            match c.next() {
                Some(first) => first.to_ascii_uppercase().to_string() + c.as_str(),
                None => String::new(),
            }
        })
        .collect()
}

fn named_type(schema: &Schema, name: &str) -> String {
    if schema.borrows(&Type::Named(name.to_string())) && schema.enum_named(name).is_none() {
        format!("{name}<'a>")
    } else {
        name.to_string()
    }
}

fn emit_union(o: &mut String, schema: &Schema, u: &Union) {
    let ty = named_type(schema, &u.name);
    let borrows = ty.ends_with("<'a>");
    let impl_lt = if borrows { "<'a>" } else { "" };
    let reader_lt = if borrows { "'a" } else { "'_" };
    writeln!(o).unwrap();
    doc(o, "", &u.doc);
    writeln!(o, "#[derive(Debug, Clone, PartialEq)]").unwrap();
    writeln!(o, "pub enum {ty} {{").unwrap();
    for v in &u.variants {
        doc(o, "    ", &v.doc);
        writeln!(o, "    {}({}),", pascal(&v.name), rust_type(schema, &v.ty)).unwrap();
    }
    writeln!(o, "}}").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "impl{impl_lt} {ty} {{").unwrap();
    writeln!(
        o,
        "    pub fn decode(r: &mut Reader<{reader_lt}>) -> Result<Self, DecodeError> {{"
    )
    .unwrap();
    writeln!(o, "        let at = r.position();").unwrap();
    writeln!(o, "        Ok(match r.u8()? {{").unwrap();
    for v in &u.variants {
        writeln!(
            o,
            "            {} => Self::{}({}),",
            v.tag,
            pascal(&v.name),
            decode_expr(schema, &v.ty, 0)
        )
        .unwrap();
    }
    writeln!(
        o,
        "            tag => return Err(DecodeError::UnknownVariant {{ union: \"{}\", tag, at }}),",
        u.name
    )
    .unwrap();
    writeln!(o, "        }})").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    writeln!(
        o,
        "    pub fn encode(&self, w: &mut Vec<u8>) -> Result<(), EncodeError> {{"
    )
    .unwrap();
    writeln!(o, "        match self {{").unwrap();
    for v in &u.variants {
        let ctx = format!("{}.{}", u.name, v.name);
        writeln!(
            o,
            "            Self::{}(v) => {{ put_u8(w, {}); {} }}",
            pascal(&v.name),
            v.tag,
            encode_stmt(schema, &v.ty, "v", &ctx, 0)
        )
        .unwrap();
    }
    writeln!(o, "        }}").unwrap();
    writeln!(o, "        Ok(())").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "    #[cfg(test)]").unwrap();
    writeln!(o, "    pub fn to_json(&self) -> serde_json::Value {{").unwrap();
    writeln!(o, "        match self {{").unwrap();
    for v in &u.variants {
        writeln!(
            o,
            "            Self::{}(v) => serde_json::json!({{ \"{}\": {} }}),",
            pascal(&v.name),
            v.name,
            json_expr(&v.ty, "v", 0)
        )
        .unwrap();
    }
    writeln!(o, "        }}").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o, "}}").unwrap();
}

fn emit_enum(o: &mut String, e: &Enum) {
    let repr = if e.repr == Type::U8 { "u8" } else { "u16" };
    writeln!(o).unwrap();
    doc(o, "", &e.doc);
    writeln!(o, "///").unwrap();
    writeln!(
        o,
        "/// Open on decode: values this version does not know are kept, not rejected."
    )
    .unwrap();
    writeln!(o, "#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]").unwrap();
    writeln!(o, "pub struct {}(pub {repr});", e.name).unwrap();
    writeln!(o).unwrap();
    writeln!(o, "impl {} {{", e.name).unwrap();
    for v in &e.variants {
        doc(o, "    ", &v.doc);
        writeln!(
            o,
            "    pub const {}: Self = Self({});",
            shout(&v.name),
            v.value
        )
        .unwrap();
    }
    writeln!(o).unwrap();
    writeln!(o, "    /// The schema name of a known value.").unwrap();
    writeln!(o, "    pub fn name(self) -> Option<&'static str> {{").unwrap();
    writeln!(o, "        match self.0 {{").unwrap();
    for v in &e.variants {
        writeln!(o, "            {} => Some(\"{}\"),", v.value, v.name).unwrap();
    }
    writeln!(o, "            _ => None,").unwrap();
    writeln!(o, "        }}").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "    #[cfg(test)]").unwrap();
    writeln!(o, "    pub fn to_json(&self) -> serde_json::Value {{").unwrap();
    writeln!(o, "        match self.name() {{").unwrap();
    writeln!(o, "            Some(name) => serde_json::json!(name),").unwrap();
    writeln!(o, "            None => serde_json::json!(self.0),").unwrap();
    writeln!(o, "        }}").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o, "}}").unwrap();
}

fn rust_type(schema: &Schema, ty: &Type) -> String {
    match ty {
        Type::U8 => "u8".into(),
        Type::U16 => "u16".into(),
        Type::U32 => "u32".into(),
        Type::U64 => "u64".into(),
        Type::I64 | Type::Millis => "i64".into(),
        Type::Bool => "bool".into(),
        Type::F64 => "f64".into(),
        Type::Str(_) => "&'a str".into(),
        Type::Bytes(_) => "&'a [u8]".into(),
        Type::List(_, inner) => format!("Vec<{}>", rust_type(schema, inner)),
        Type::Opt(inner) => format!("Option<{}>", rust_type(schema, inner)),
        Type::Record => "RecordRef<'a>".into(),
        Type::Records => "Records<'a>".into(),
        Type::Named(name) => named_type(schema, name),
    }
}

fn width(w: Width) -> &'static str {
    match w {
        Width::W16 => "16",
        Width::W32 => "32",
    }
}

/// An expression that decodes one `ty` from reader `r`.
fn decode_expr(schema: &Schema, ty: &Type, depth: usize) -> String {
    match ty {
        Type::U8 => "r.u8()?".into(),
        Type::U16 => "r.u16()?".into(),
        Type::U32 => "r.u32()?".into(),
        Type::U64 => "r.u64()?".into(),
        Type::I64 | Type::Millis => "r.i64()?".into(),
        Type::Bool => "r.bool()?".into(),
        Type::F64 => "r.f64()?".into(),
        Type::Str(w) => format!("r.str{}()?", width(*w)),
        Type::Bytes(w) => format!("r.bytes{}()?", width(*w)),
        Type::List(w, inner) => {
            let n = format!("n{depth}");
            let v = format!("v{depth}");
            format!(
                "{{ let {n} = r.len{}()?; let mut {v} = Vec::with_capacity({n}.min(r.remaining())); for _ in 0..{n} {{ {v}.push({}); }} {v} }}",
                width(*w),
                decode_expr(schema, inner, depth + 1)
            )
        }
        Type::Opt(inner) => format!(
            "if r.present()? {{ Some({}) }} else {{ None }}",
            decode_expr(schema, inner, depth + 1)
        ),
        Type::Record => "RecordRef::decode(r)?".into(),
        Type::Records => "Records::decode(r)?".into(),
        Type::Named(name) => match schema.enum_named(name) {
            Some(e) if e.repr == Type::U8 => format!("{name}(r.u8()?)"),
            Some(_) => format!("{name}(r.u16()?)"),
            None => format!("{name}::decode(r)?"),
        },
    }
}

/// Statements that encode the value behind reference expression `x` into `w`.
fn encode_stmt(schema: &Schema, ty: &Type, x: &str, ctx: &str, depth: usize) -> String {
    match ty {
        Type::U8 => format!("put_u8(w, *{x});"),
        Type::U16 => format!("put_u16(w, *{x});"),
        Type::U32 => format!("put_u32(w, *{x});"),
        Type::U64 => format!("put_u64(w, *{x});"),
        Type::I64 | Type::Millis => format!("put_i64(w, *{x});"),
        Type::Bool => format!("put_u8(w, *{x} as u8);"),
        Type::F64 => format!("put_f64(w, *{x});"),
        Type::Str(wd) => format!("put_str{}(w, {x}, \"{ctx}\")?;", width(*wd)),
        Type::Bytes(wd) => format!("put_bytes{}(w, {x}, \"{ctx}\")?;", width(*wd)),
        Type::List(wd, inner) => {
            let item = format!("item{depth}");
            format!(
                "put_len{}(w, {x}.len(), \"{ctx}\")?; for {item} in {x}.iter() {{ {} }}",
                width(*wd),
                encode_stmt(schema, inner, &item, ctx, depth + 1)
            )
        }
        Type::Opt(inner) => {
            let v = format!("some{depth}");
            format!(
                "match {x} {{ Some({v}) => {{ put_u8(w, 1); {} }} None => put_u8(w, 0), }}",
                encode_stmt(schema, inner, v.as_str(), ctx, depth + 1)
            )
        }
        Type::Record | Type::Records => format!("{x}.encode(w)?;"),
        Type::Named(name) => match schema.enum_named(name) {
            Some(e) if e.repr == Type::U8 => format!("put_u8(w, {x}.0);"),
            Some(_) => format!("put_u16(w, {x}.0);"),
            None => format!("{x}.encode(w)?;"),
        },
    }
}

/// An expression turning the value behind reference `x` into `serde_json::Value`.
fn json_expr(ty: &Type, x: &str, depth: usize) -> String {
    match ty {
        Type::U8 | Type::U16 | Type::U32 | Type::Millis | Type::Bool | Type::F64 => {
            format!("serde_json::json!(*{x})")
        }
        Type::U64 | Type::I64 => format!("serde_json::json!({x}.to_string())"),
        Type::Str(_) => format!("serde_json::json!(*{x})"),
        Type::Bytes(_) => format!("serde_json::json!(hex({x}))"),
        Type::List(_, inner) => {
            let item = format!("item{depth}");
            format!(
                "serde_json::Value::Array({x}.iter().map(|{item}| {}).collect())",
                json_expr(inner, &item, depth + 1)
            )
        }
        Type::Opt(inner) => {
            let v = format!("some{depth}");
            format!(
                "match {x} {{ Some({v}) => {}, None => serde_json::Value::Null }}",
                json_expr(inner, &v, depth + 1)
            )
        }
        Type::Record | Type::Records | Type::Named(_) => format!("{x}.to_json()"),
    }
}

fn emit_struct(o: &mut String, schema: &Schema, s: &Struct) {
    let borrows = schema.struct_borrows(s);
    let lt = if borrows { "<'a>" } else { "" };
    let reader_lt = if borrows { "'a" } else { "'_" };
    writeln!(o).unwrap();
    doc(o, "", &s.doc);
    writeln!(o, "#[derive(Debug, Clone, PartialEq)]").unwrap();
    writeln!(o, "pub struct {}{lt} {{", s.name).unwrap();
    for f in &s.fields {
        doc(o, "    ", &f.doc);
        writeln!(o, "    pub {}: {},", f.name, rust_type(schema, &f.ty)).unwrap();
    }
    writeln!(o, "}}").unwrap();
    writeln!(o).unwrap();
    let impl_lt = if borrows { "<'a>" } else { "" };
    writeln!(o, "impl{impl_lt} {}{lt} {{", s.name).unwrap();
    if let Some(kind) = s.kind {
        writeln!(o, "    pub const KIND: u16 = {kind:#06x};").unwrap();
        writeln!(o).unwrap();
    }
    let r = if s.fields.is_empty() { "_r" } else { "r" };
    writeln!(
        o,
        "    pub fn decode({r}: &mut Reader<{reader_lt}>) -> Result<Self, DecodeError> {{"
    )
    .unwrap();
    writeln!(o, "        Ok(Self {{").unwrap();
    for f in &s.fields {
        writeln!(
            o,
            "            {}: {},",
            f.name,
            decode_expr(schema, &f.ty, 0)
        )
        .unwrap();
    }
    writeln!(o, "        }})").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    let w = if s.fields.is_empty() { "_w" } else { "w" };
    writeln!(
        o,
        "    pub fn encode(&self, {w}: &mut Vec<u8>) -> Result<(), EncodeError> {{"
    )
    .unwrap();
    for f in &s.fields {
        let ctx = format!("{}.{}", s.name, f.name);
        writeln!(o, "        let {0} = &self.{0};", f.name).unwrap();
        writeln!(
            o,
            "        {}",
            encode_stmt(schema, &f.ty, &f.name, &ctx, 0)
        )
        .unwrap();
    }
    writeln!(o, "        Ok(())").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "    #[cfg(test)]").unwrap();
    writeln!(o, "    pub fn to_json(&self) -> serde_json::Value {{").unwrap();
    writeln!(o, "        #[allow(unused_mut)]").unwrap();
    writeln!(o, "        let mut m = serde_json::Map::new();").unwrap();
    for f in &s.fields {
        writeln!(o, "        let {0} = &self.{0};", f.name).unwrap();
        writeln!(
            o,
            "        m.insert(\"{}\".into(), {});",
            f.name,
            json_expr(&f.ty, &f.name, 0)
        )
        .unwrap();
    }
    writeln!(o, "        serde_json::Value::Object(m)").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o, "}}").unwrap();
}

fn emit_frame_enum(o: &mut String, schema: &Schema) {
    writeln!(o).unwrap();
    writeln!(o, "/// Every frame this version knows.").unwrap();
    writeln!(o, "#[derive(Debug, Clone, PartialEq)]").unwrap();
    writeln!(o, "pub enum Frame<'a> {{").unwrap();
    for f in schema.frames() {
        writeln!(
            o,
            "    {}({}),",
            f.name,
            rust_type(schema, &Type::Named(f.name.clone()))
        )
        .unwrap();
    }
    writeln!(o, "}}").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "impl<'a> Frame<'a> {{").unwrap();
    writeln!(o, "    pub fn kind(&self) -> u16 {{").unwrap();
    writeln!(o, "        match self {{").unwrap();
    for f in schema.frames() {
        writeln!(o, "            Frame::{0}(_) => {0}::KIND,", f.name).unwrap();
    }
    writeln!(o, "        }}").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "    pub fn name(&self) -> &'static str {{").unwrap();
    writeln!(o, "        match self {{").unwrap();
    for f in schema.frames() {
        writeln!(o, "            Frame::{0}(_) => \"{0}\",", f.name).unwrap();
    }
    writeln!(o, "        }}").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    writeln!(
        o,
        "    /// Decodes a frame body. `Ok(None)` for a kind this version does not know."
    )
    .unwrap();
    writeln!(
        o,
        "    /// Bytes after the declared fields are ignored: later minor versions may"
    )
    .unwrap();
    writeln!(o, "    /// append fields to a frame.").unwrap();
    writeln!(
        o,
        "    pub fn decode(kind: u16, body: &'a [u8]) -> Result<Option<Self>, DecodeError> {{"
    )
    .unwrap();
    writeln!(o, "        let r = &mut Reader::new(body);").unwrap();
    writeln!(o, "        Ok(Some(match kind {{").unwrap();
    for f in schema.frames() {
        writeln!(
            o,
            "            {0}::KIND => Frame::{0}({0}::decode(r)?),",
            f.name
        )
        .unwrap();
    }
    writeln!(o, "            _ => return Ok(None),").unwrap();
    writeln!(o, "        }}))").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    writeln!(
        o,
        "    pub fn encode_body(&self, w: &mut Vec<u8>) -> Result<(), EncodeError> {{"
    )
    .unwrap();
    writeln!(o, "        match self {{").unwrap();
    for f in schema.frames() {
        writeln!(o, "            Frame::{}(f) => f.encode(w),", f.name).unwrap();
    }
    writeln!(o, "        }}").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "    #[cfg(test)]").unwrap();
    writeln!(o, "    pub fn body_json(&self) -> serde_json::Value {{").unwrap();
    writeln!(o, "        match self {{").unwrap();
    for f in schema.frames() {
        writeln!(o, "            Frame::{}(f) => f.to_json(),", f.name).unwrap();
    }
    writeln!(o, "        }}").unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o, "}}").unwrap();
}

fn emit_record_json(o: &mut String) {
    writeln!(o).unwrap();
    writeln!(o, "#[cfg(test)]").unwrap();
    writeln!(o, "impl RecordRef<'_> {{").unwrap();
    writeln!(o, "    pub fn to_json(&self) -> serde_json::Value {{").unwrap();
    writeln!(o, "        let event = {EVENT_RECORD}::decode(&mut Reader::new(self.body)).expect(\"record body\");").unwrap();
    writeln!(
        o,
        "        serde_json::json!({{ \"flags\": self.flags, \"event\": event.to_json() }})"
    )
    .unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o, "}}").unwrap();
    writeln!(o).unwrap();
    writeln!(o, "#[cfg(test)]").unwrap();
    writeln!(o, "impl Records<'_> {{").unwrap();
    writeln!(o, "    pub fn to_json(&self) -> serde_json::Value {{").unwrap();
    writeln!(
        o,
        "        serde_json::Value::Array(self.iter().map(|r| r.to_json()).collect())"
    )
    .unwrap();
    writeln!(o, "    }}").unwrap();
    writeln!(o, "}}").unwrap();
}
